const BASE_RATES={emerald:1,diamond:9,gold_ingot:3,wheat:.25};function priceFor(e,t){const n=BASE_RATES[e]||0;return Math.max(1,Math.round(n*t))}function renderStall(e){return e.map(e=>e.name+" x"+e.qty+" = "+priceFor(e.id,e.qty)+"em").join("\n")}window.TradingHub={priceFor,renderStall};
